import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-react-building-collapsible-react-accordion":{"intro":"In this lab, we will explore how to implement a collapsible accordion menu in React using components and hooks. The purpose of this lab is to provide a hands-on experience in building a functional accordion menu with multiple collapsible content elements. By the end of this lab, you will have a good understanding of how to use React to create dynamic and interactive user interfaces.","steps":[{"title":"Collapsible Accordion","body":["To render an accordion menu with multiple collapsible content elements, you can follow these steps:"],"code":[{"lang":"css","text":".accordion-item.collapsed {\n  display: none;\n}\n\n.accordion-item.expanded {\n  display: block;\n}\n\n.accordion-button {\n  display: block;\n  width: 100%;\n}"},{"lang":"jsx","text":"const AccordionItem = ({ label, isCollapsed, handleClick, children }) => {\n  return (\n    <>\n      <button className=\"accordion-button\" onClick={handleClick}>\n        {label}\n      </button>\n      <div\n        className={`accordion-item ${isCollapsed ? \"collapsed\" : \"expanded\"}`}\n        aria-expanded={isCollapsed}\n      >\n        {children}\n      </div>\n    </>\n  );\n};\n\nconst Accordion = ({ defaultIndex, onItemClick, children }) => {\n  const [bindIndex, setBindIndex] = React.useState(defaultIndex);\n\n  const changeItem = (itemIndex) => {\n    if (typeof onItemClick === \"function\") onItemClick(itemIndex);\n    if (itemIndex !== bindIndex) setBindIndex(itemIndex);\n  };\n\n  const items = children.filter((item) => item.type.name === \"AccordionItem\");\n\n  return (\n    <>\n      {items.map(({ props }) => (\n        <AccordionItem\n          isCollapsed={bindIndex !== props.index}\n          label={props.label}\n          handleClick={() => changeItem(props.index)}\n          children={props.children}\n        />\n      ))}\n    </>\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Accordion defaultIndex=\"1\" onItemClick={console.log}>\n    <AccordionItem label=\"A\" index=\"1\">\n      Lorem ipsum\n    </AccordionItem>\n    <AccordionItem label=\"B\" index=\"2\">\n      Dolor sit amet\n    </AccordionItem>\n  </Accordion>\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Collapsible Accordion</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-create-closable-react-alert":{"intro":"In this lab, we will be creating a Closable Alert component using React. The component will allow users to display a message of a specific type and close the alert when they are done with it. By the end of this lab, you will have learned how to use the useState() and useEffect() hooks to create a dynamic component that can be easily customized to fit your needs.","steps":[{"title":"Closable Alert","body":["Renders an alert component with the type prop.","The Alert component takes in the following props:","• isDefaultShown: a boolean that determines if the alert is initially shown or not (default is false) • timeout: a number that specifies the duration in milliseconds before the alert fades out (default is 250) • type: a string that determines the type of alert (e.g. \"warning\", \"error\", \"info\") • message: a string that contains the message to display in the alert","The component does the following:"],"code":[{"lang":"css","text":"@keyframes leave {\n  0% {\n    opacity: 1;\n  }\n  100% {\n    opacity: 0;\n  }\n}\n\n.alert {\n  padding: 0.75rem 0.5rem;\n  margin-bottom: 0.5rem;\n  text-align: left;\n  padding-right: 40px;\n  border-radius: 4px;\n  font-size: 16px;\n  position: relative;\n}\n\n.alert.warning {\n  color: #856404;\n  background-color: #fff3cd;\n  border-color: #ffeeba;\n}\n\n.alert.error {\n  color: #721c24;\n  background-color: #f8d7da;\n  border-color: #f5c6cb;\n}\n\n.alert.leaving {\n  animation: leave 0.5s forwards;\n}\n\n.alert .close {\n  position: absolute;\n  top: 0;\n  right: 0;\n  padding: 0 0.75rem;\n  color: #333;\n  border: 0;\n  height: 100%;\n  cursor: pointer;\n  background: none;\n  font-weight: 600;\n  font-size: 16px;\n}"},{"lang":"jsx","text":"const Alert = ({ isDefaultShown = false, timeout = 250, type, message }) => {\n  const [isShown, setIsShown] = React.useState(isDefaultShown);\n  const [isLeaving, setIsLeaving] = React.useState(false);\n\n  let timeoutId = null;\n\n  React.useEffect(() => {\n    setIsShown(true);\n    return () => {\n      clearTimeout(timeoutId);\n    };\n  }, [isDefaultShown, timeout, timeoutId]);\n\n  const closeAlert = () => {\n    setIsLeaving(true);\n    timeoutId = setTimeout(() => {\n      setIsLeaving(false);\n      setIsShown(false);\n    }, timeout);\n  };\n\n  return (\n    isShown && (\n      <div\n        className={`alert ${type} ${isLeaving ? \"leaving\" : \"\"}`}\n        role=\"alert\"\n      >\n        <button className=\"close\" onClick={closeAlert} />\n        {message}\n      </div>\n    )\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Alert type=\"info\" message=\"This is info\" />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Closable Alert</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-carousel-component-creation":{"intro":"In this lab, we will explore how to create a carousel component using React. A carousel is a popular UI element that allows users to cycle through a set of images or content. By using the useState() and useEffect() hooks, we can build a simple yet functional carousel that automatically scrolls through a set of items.","steps":[{"title":"Carousel","body":["This code renders a carousel component. Here are the steps it takes:","• It uses the useState() hook to create the active state variable and initializes it to 0 (the index of the first item in the carousel). • It uses the useEffect() hook to set up a timer with setTimeout(). When the timer fires, it updates the value of active to the index of the next item in the carousel (using the modulo operator to wrap around to the beginning if necessary). It also cleans up the timer when the component unmounts. • It computes the className for each carousel item by mapping over them and applying the appropriate class based on whether the item is currently active or not. • It renders the carousel items using…","The CSS styles define the layout of the carousel and its items. The carousel container has position: relative, while the items have position: absolute and visibility: hidden by default. When an item is active, it gets a visible class, which sets its visibility to visible."],"code":[{"lang":"css","text":".carousel {\n  position: relative;\n}\n\n.carousel-item {\n  position: absolute;\n  visibility: hidden;\n}\n\n.carousel-item.visible {\n  visibility: visible;\n}"},{"lang":"jsx","text":"const Carousel = ({ carouselItems, ...rest }) => {\n  const [active, setActive] = React.useState(0);\n  let scrollInterval = null;\n\n  React.useEffect(() => {\n    scrollInterval = setTimeout(() => {\n      setActive((active + 1) % carouselItems.length);\n    }, 2000);\n    return () => clearTimeout(scrollInterval);\n  });\n\n  return (\n    <div className=\"carousel\">\n      {carouselItems.map((item, index) => {\n        const activeClass = active === index ? \" visible\" : \"\";\n        return React.cloneElement(item, {\n          ...rest,\n          className: `carousel-item${activeClass}`\n        });\n      })}\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Carousel\n    carouselItems={[\n      <div>carousel item 1</div>,\n      <div>carousel item 2</div>,\n      <div>carousel item 3</div>\n    ]}\n  />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Carousel</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-create-collapsible-react-components":{"intro":"In this lab, we will explore how to create a collapsible content component in React using the useState hook. This component will allow users to toggle the visibility of content by clicking on a button, making it a useful tool for organizing and presenting information on a webpage. By the end of this lab, you will have a better understanding of how to create reusable components in React that improve the accessibility and user experience of your web applications.","steps":[{"title":"Collapsible Content","body":["This function renders a collapsible component with a button that toggles the visibility of its content. Here's how to use it:","• Use the useState() hook to create the isCollapsed state variable, which represents whether the content is currently collapsed or expanded. Initialize it to collapsed. • Use the <button> element to toggle the isCollapsed state and show/hide the content passed down via the children prop. • Use isCollapsed to apply the appropriate CSS class to the content container, either collapsed or expanded, which determines its appearance. • Update the aria-expanded attribute of the content container based on the isCollapsed state, to make the component accessible to users with disabilities.","Here's the CSS code needed for this component:","And here's the JavaScript code:"],"code":[{"lang":"css","text":".collapse-button {\n  display: block;\n  width: 100%;\n}\n\n.collapse-content.collapsed {\n  display: none;\n}\n\n.collapse-content.expanded {\n  display: block;\n}"},{"lang":"jsx","text":"const Collapse = ({ collapsed, children }) => {\n  const [isCollapsed, setIsCollapsed] = React.useState(collapsed);\n\n  return (\n    <>\n      <button\n        className=\"collapse-button\"\n        onClick={() => setIsCollapsed(!isCollapsed)}\n      >\n        {isCollapsed ? \"Show\" : \"Hide\"} content\n      </button>\n      <div\n        className={`collapse-content ${isCollapsed ? \"collapsed\" : \"expanded\"}`}\n        aria-expanded={isCollapsed}\n      >\n        {children}\n      </div>\n    </>\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Collapse>\n    <h1>This is a collapse</h1>\n    <p>Hello world!</p>\n  </Collapse>\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Collapsible Content</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-countdown-timer-component":{"intro":"In this lab, we will be building a countdown timer component using React. The timer will accept props for the starting time and will render a visual representation of the time left. It will also include buttons to pause, resume, and restart the timer, and will display a message when the time runs out. By completing this lab, you will gain experience using state and effects in React to build dynamic and interactive components.","steps":[{"title":"Countdown Timer","body":["This code creates a countdown timer that prints a message when it reaches zero. To implement it, the following steps are taken:","• Use the useState() hook to create a state variable time that holds the time value. Initialize it from the props and destructure it into its components. • Use the useState() hook to create the paused and over state variables, which are used to prevent the timer from ticking if it's paused or the time has run out. • Create a method tick, that updates the time values based on the current value (i.e. decreasing the time by one second). • Create a method reset, that resets all state variables to their initial states. • Use the the useEffect() hook to call the tick method every second via the use of setInterval() and use…"],"code":[{"lang":"jsx","text":"const CountDown = ({ hours = 0, minutes = 0, seconds = 0 }) => {\n  const [paused, setPaused] = React.useState(false);\n  const [over, setOver] = React.useState(false);\n  const [[h, m, s], setTime] = React.useState([hours, minutes, seconds]);\n\n  const tick = () => {\n    if (paused || over) return;\n    if (h === 0 && m === 0 && s === 0) setOver(true);\n    else if (m === 0 && s === 0) setTime([h - 1, 59, 59]);\n    else if (s == 0) setTime([h, m - 1, 59]);\n    else setTime([h, m, s - 1]);\n  };\n\n  const reset = () => {\n    setTime([parseInt(hours), parseInt(minutes), parseInt(seconds)]);\n    setPaused(false);\n    setOver(false);\n  };\n\n  React.useEffect(() => {\n    const timerID = setInterval(tick, 1000);\n    return () => clearInterval(timerID);\n  });\n\n  return (\n    <div>\n      <p>\n        {`${h.toString().padStart(2, \"0\")}:${m.toString().padStart(2, \"0\")}:${s\n          .toString()\n          .padStart(2, \"0\")}`}\n      </p>\n      {over && <div>Time's up!</div>}\n      <button onClick={() => setPaused(!paused)}>\n        {paused ? \"Resume\" : \"Pause\"}\n      </button>\n      <button onClick={reset}>Restart</button>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <CountDown hours={1} minutes={45} />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Countdown Timer</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-file-drag-and-drop-area":{"intro":"In this lab, we will learn how to create a file drag and drop component in React using the useState and useEffect hooks. This component allows users to easily drag and drop files onto a designated area and triggers a callback function with the dropped file as an argument. By the end of this lab, you will have a better understanding of how to handle drag and drop functionality in React.","steps":[{"title":"File Drag and Drop Area","body":["This component allows for drag and drop functionality for a single file. To implement this component, follow these steps:","• Create a reference called dropRef and bind it to the component's wrapper. • Use the useState() hook to create the drag and filename variables. Initialize them to false and '' respectively. • The variables dragCounter and drag are used to determine if a file is being dragged, while filename is used to store the dropped file's name. • Create the handleDrag, handleDragIn, handleDragOut, and handleDrop methods to handle drag and drop functionality. handleDrag prevents the browser from opening the dragged file, handleDragIn and handleDragOut handle the dragged file entering and exiting the component, and handleDrop handles the file…","Here is the CSS for the component:","Here is the JSX for the component:"],"code":[{"lang":"css","text":".filedrop {\n  min-height: 120px;\n  border: 3px solid #d3d3d3;\n  text-align: center;\n  font-size: 24px;\n  padding: 32px;\n  border-radius: 4px;\n}\n\n.filedrop.drag {\n  border: 3px dashed #1e90ff;\n}\n\n.filedrop.ready {\n  border: 3px solid #32cd32;\n}"},{"lang":"jsx","text":"const FileDrop = ({ onDrop }) => {\n  const [drag, setDrag] = React.useState(false);\n  const [filename, setFilename] = React.useState(\"\");\n  const dropRef = React.useRef(null);\n  let dragCounter = 0;\n\n  const handleDrag = (e) => {\n    e.preventDefault();\n    e.stopPropagation();\n  };\n\n  const handleDragIn = (e) => {\n    e.preventDefault();\n    e.stopPropagation();\n    dragCounter++;\n    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) setDrag(true);\n  };\n\n  const handleDragOut = (e) => {\n    e.preventDefault();\n    e.stopPropagation();\n    dragCounter--;\n    if (dragCounter === 0) setDrag(false);\n  };\n\n  const handleDrop = (e) => {\n    e.preventDefault();\n    e.stopPropagation();\n    setDrag(false);\n    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {\n      onDrop(e.dataTransfer.files[0]);\n      setFilename(e.dataTransfer.files[0].name);\n      e.dataTransfer.clearData();\n      dragCounter = 0;\n    }\n  };\n\n  React.useEffect(() => {\n    const div = dropRef.current;\n    div.addEventListener(\"dragenter\", handleDragIn);\n    div.addEventListener(\"dragleave\", handleDragOut);\n    div.addEventListener(\"dragover\", handleDrag);\n    div.addEventListener(\"drop\", handleDrop);\n    return () => {\n      div.removeEventListener(\"dragenter\", handleDragIn);\n      div.removeEventListener(\"dragleave\", handleDragOut);\n      div.removeEventListener(\"dragover\", handleDrag);\n      div.removeEventListener(\"drop\", handleDrop);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>File Drag and Drop Area</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-textarea-with-character-limit":{"intro":"In this lab, we will be building a limited textarea component using React. The purpose of this lab is to provide a hands-on experience in utilizing React hooks, such as useState() and useCallback(), to create a component that limits the number of characters a user can input in a textarea. By the end of this lab, you will have a functional textarea component that displays the character count and limits the number of characters a user can input.","steps":[{"title":"Textarea with Character Limit","body":["• Simplified the comments to provide a more concise overview of what each part of the code does. • Removed unnecessary code comments. • Removed the setContent function from the useCallback dependency array, as it doesn't need to be there. • Added parentheses around the text argument in the useCallback function for consistency. • Used arrow functions for the onChange event handler for brevity."],"code":[{"lang":"jsx","text":"const LimitedTextarea = ({ rows, cols, value, limit }) => {\n  const [content, setContent] = React.useState(value.slice(0, limit));\n\n  const setFormattedContent = React.useCallback(\n    (text) => {\n      setContent(text.slice(0, limit));\n    },\n    [limit]\n  );\n\n  return (\n    <>\n      <textarea\n        rows={rows}\n        cols={cols}\n        onChange={(event) => setFormattedContent(event.target.value)}\n        value={content}\n      />\n      <p>\n        {content.length}/{limit}\n      </p>\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <LimitedTextarea limit={32} value=\"Hello!\" />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Textarea With Character Limit</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-textarea-with-word-limit":{"intro":"In this lab, we will be creating a React component that renders a textarea with a word limit. The component will utilize React hooks such as useState(), useCallback(), and useEffect() to manage the state of the textarea and limit the number of words that can be entered. This lab provides a practical example of how to utilize hooks to create reusable React components.","steps":[{"title":"Textarea with Word Limit","body":["• Added comments to explain what each part of the code does. • Simplified the logic in setFormattedContent to make it more concise. • Moved the setContent function to the end of the function call to make it easier to read. • Reordered the props in the <textarea> component for consistency. • Removed unnecessary spaces and line breaks."],"code":[{"lang":"jsx","text":"// Renders a textarea component with a word limit.\nconst LimitedWordTextarea = ({ rows, cols, value, limit }) => {\n  const [{ content, wordCount }, setContent] = React.useState({\n    content: value,\n    wordCount: 0\n  });\n\n  // Create a memoized function that formats the input text.\n  const setFormattedContent = React.useCallback(\n    (text) => {\n      const words = text.split(\" \").filter(Boolean);\n      const truncated = words.slice(0, limit).join(\" \");\n      setContent({\n        content: words.length > limit ? truncated : text,\n        wordCount: words.length > limit ? limit : words.length\n      });\n    },\n    [limit, setContent]\n  );\n\n  // Call setFormattedContent on the initial value of content.\n  React.useEffect(() => {\n    setFormattedContent(content);\n  }, []);\n\n  return (\n    <>\n      <textarea\n        rows={rows}\n        cols={cols}\n        value={content}\n        onChange={(event) => setFormattedContent(event.target.value)}\n      />\n      <p>\n        {wordCount}/{limit}\n      </p>\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <LimitedWordTextarea limit={5} value=\"Hello there!\" />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Textarea With Word Limit</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-create-reusable-react-spinner":{"intro":"In this lab, we will learn how to create a spinning loader component using React and CSS. The purpose of this component is to provide a visual indication to the user that the application is loading or processing data. By the end of this lab, you will have a reusable loader component that you can use in your React projects.","steps":[{"title":"Spinning Loader","body":["**Renders a spinning loader component.**","To render a spinning loader component, follow these steps:","• Render an SVG element whose dimensions are determined by the size prop. • Use CSS to animate the SVG, creating a spinning animation. Specifically, add the .loader class to the SVG and set the animation property to rotate 2s linear infinite. Also, define the rotate keyframes with a transform property that rotates the SVG 360 degrees. • Add a circle element to the SVG, which represents the spinning circle. To animate the circle, add the .loader circle selector and set the animation property to dash 1.5s ease-in-out infinite. Also, define the dash keyframes with stroke-dasharray and stroke-dashoffset properties that create a…","To use the Loader component with a size of 24, call ReactDOM.createRoot(document.getElementById('root')).render(<Loader size={24} />);."],"code":[{"lang":"css","text":".loader {\n  animation: rotate 2s linear infinite;\n}\n\n@keyframes rotate {\n  100% {\n    transform: rotate(360deg);\n  }\n}\n\n.loader circle {\n  animation: dash 1.5s ease-in-out infinite;\n}\n\n@keyframes dash {\n  0% {\n    stroke-dasharray: 1, 150;\n    stroke-dashoffset: 0;\n  }\n  50% {\n    stroke-dasharray: 90, 150;\n    stroke-dashoffset: -35;\n  }\n  100% {\n    stroke-dasharray: 90, 150;\n    stroke-dashoffset: -124;\n  }\n}"},{"lang":"jsx","text":"const Loader = ({ size }) => {\n  return (\n    <svg\n      className=\"loader\"\n      width={size}\n      height={size}\n      viewBox=\"0 0 24 24\"\n      fill=\"none\"\n      stroke=\"currentColor\"\n      strokeWidth=\"2\"\n      strokeLinecap=\"round\"\n      strokeLinejoin=\"round\"\n    >\n      <circle cx=\"12\" cy=\"12\" r=\"10\" />\n    </svg>\n  );\n};"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Spinning Loader</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-creating-reusable-modal-component-in-react":{"intro":"In this lab, we will explore how to create a Modal component in React that can be controlled through events. The Modal component will have a close button, and the keyboard event listener will be used to close the modal when the Esc key is pressed. By the end of this lab, you will have a good understanding of how to create a reusable Modal component that can be easily integrated into any React project.","steps":[{"title":"Modal Dialog","body":["This code renders a Modal component that can be controlled through events. To use the component, you can import Modal once and then display it by passing a boolean value to the isVisible attribute.","The Modal component has the following features:"],"code":[{"lang":"jsx","text":"const Modal = ({ isVisible = false, title, content, footer, onClose }) => {\n  const keydownHandler = ({ key }) => {\n    switch (key) {\n      case \"Escape\":\n        onClose();\n        break;\n      default:\n    }\n  };\n\n  React.useEffect(() => {\n    document.addEventListener(\"keydown\", keydownHandler);\n    return () => document.removeEventListener(\"keydown\", keydownHandler);\n  });\n\n  return !isVisible ? null : (\n    <div className=\"modal\" onClick={onClose}>\n      <div className=\"modal-dialog\" onClick={(e) => e.stopPropagation()}>\n        <div className=\"modal-header\">\n          <h3 className=\"modal-title\">{title}</h3>\n          <span className=\"modal-close\" onClick={onClose}>\n            &times;\n          </span>\n        </div>\n        <div className=\"modal-body\">\n          <div className=\"modal-content\">{content}</div>\n        </div>\n        {footer && <div className=\"modal-footer\">{footer}</div>}\n      </div>\n    </div>\n  );\n};"},{"lang":"css","text":".modal {\n  position: fixed;\n  top: 0;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  width: 100%;\n  z-index: 9999;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: rgba(0, 0, 0, 0.25);\n  animation-name: appear;\n  animation-duration: 300ms;\n}\n\n.modal-dialog {\n  width: 100%;\n  max-width: 550px;\n  background: white;\n  position: relative;\n  margin: 0 20px;\n  max-height: calc(100vh - 40px);\n  text-align: left;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  box-shadow:\n    0 4px 8px 0 rgba(0, 0, 0, 0.2),\n    0 6px 20px 0 rgba(0, 0, 0, 0.19);\n  -webkit-animation-name: animatetop;\n  -webkit-animation-duration: 0.4s;\n  animation-name: slide-in;\n  animation-duration: 0.5s;\n}\n\n.modal-header,\n.modal-footer {\n  display: flex;\n  align-items: center;\n  padding: 1rem;\n}\n\n.modal-header {\n  border-bottom: 1px solid #dbdbdb;\n  justify-content: space-between;\n}"},{"lang":"jsx","text":"const App = () => {\n  const [isModal, setModal] = React.useState(false);\n  return (\n    <>\n      <button onClick={() => setModal(true)}>Click Here</button>\n      <Modal\n        isVisible={isModal}\n        title=\"Modal Title\"\n        content={<p>Add your content here</p>}\n        footer={<button>Cancel</button>}\n        onClose={() => setModal(false)}\n      />\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Modal Dialog</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-stateful-checkbox-with-multiple-selection":{"intro":"In this lab, we will learn how to create a stateful checkbox with multiple selection using React. This lab will guide you through the process of rendering a checkbox list, updating its state, and passing the selected value/values to the parent component using a callback function. By the end of this lab, you will be able to create a reusable checkbox component that can be used in any React project.","steps":[{"title":"Stateful Checkbox with Multiple Selection","body":["Stateful Checkbox With Multiple Selection","This code renders a list of checkboxes and sends the selected value(s) to the parent component using a callback function. Here are the steps to create it:","Here is an example of how to use it:"],"code":[{"lang":"jsx","text":"const MultiselectCheckbox = ({ options, onChange }) => {\n  const [data, setData] = React.useState(options);\n\n  const toggle = (index) => {\n    const newData = [...data];\n    newData[index] = {\n      ...newData[index],\n      checked: !newData[index].checked\n    };\n    setData(newData);\n    onChange(newData.filter((item) => item.checked));\n  };\n\n  return (\n    <>\n      {data.map((item, index) => (\n        <label key={item.label}>\n          <input\n            type=\"checkbox\"\n            checked={item.checked || false}\n            onChange={() => toggle(index)}\n          />\n          {item.label}\n        </label>\n      ))}\n    </>\n  );\n};"},{"lang":"jsx","text":"const options = [{ label: \"Item One\" }, { label: \"Item Two\" }];\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <MultiselectCheckbox\n    options={options}\n    onChange={(selected) => {\n      console.log(selected);\n    }}\n  />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Stateful Checkbox With Multiple Selection</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-button-with-ripple-effect":{"intro":"In this lab, we will learn how to create a button with a ripple effect animation using React. The purpose of this lab is to help you understand how to use React hooks, such as useState() and useEffect(), to manage the state of the button and trigger the animation. By the end of this lab, you will be able to create interactive and visually appealing buttons for your React applications.","steps":[{"title":"Button with Ripple Effect","body":["Here's the code for the RippleButton component:","You can use this component like this:","And here's the CSS for the RippleButton component:"],"code":[{"lang":"jsx","text":"const RippleButton = ({ children, onClick }) => {\n  const [coords, setCoords] = React.useState({ x: -1, y: -1 });\n  const [isRippling, setIsRippling] = React.useState(false);\n\n  React.useEffect(() => {\n    if (coords.x !== -1 && coords.y !== -1) {\n      setIsRippling(true);\n      setTimeout(() => setIsRippling(false), 300);\n    } else setIsRippling(false);\n  }, [coords]);\n\n  React.useEffect(() => {\n    if (!isRippling) setCoords({ x: -1, y: -1 });\n  }, [isRippling]);\n\n  return (\n    <button\n      className=\"ripple-button\"\n      onClick={(e) => {\n        const rect = e.target.getBoundingClientRect();\n        setCoords({ x: e.clientX - rect.left, y: e.clientY - rect.top });\n        onClick && onClick(e);\n      }}\n    >\n      {isRippling && (\n        <span\n          className=\"ripple\"\n          style={{\n            left: coords.x,\n            top: coords.y\n          }}\n        />\n      )}\n      <span className=\"content\">{children}</span>\n    </button>\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <RippleButton onClick={(e) => console.log(e)}>Click me</RippleButton>\n);"},{"lang":"css","text":".ripple-button {\n  border-radius: 4px;\n  border: none;\n  margin: 8px;\n  padding: 14px 24px;\n  background: #1976d2;\n  color: #fff;\n  overflow: hidden;\n  position: relative;\n  cursor: pointer;\n}\n\n.ripple-button > .ripple {\n  width: 20px;\n  height: 20px;\n  position: absolute;\n  background: #63a4ff;\n  display: block;\n  content: \"\";\n  border-radius: 9999px;\n  opacity: 1;\n  animation: 0.9s ease 1 forwards ripple-effect;\n}\n\n@keyframes ripple-effect {\n  0% {\n    transform: scale(1);\n    opacity: 1;\n  }\n  50% {\n    transform: scale(10);\n    opacity: 0.375;\n  }\n  100% {\n    transform: scale(35);\n    opacity: 0;\n  }\n}\n\n.ripple-button > .content {\n  position: relative;\n  z-index: 2;\n}"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Button With Ripple Effect</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-uncontrolled-select-element":{"intro":"In this lab, we will learn how to create an uncontrolled <select> element in React using callback functions to pass its value to the parent component. We will use the selectedValue prop to set the initial value of the <select> element, and the onChange event to send the new value to the parent. This lab will also cover how to use Array.prototype.map() to create <option> elements for each passed value.","steps":[{"title":"Uncontrolled Select Element","body":["This is a component that renders a controlled <select> element. The component accepts an array of values and a callback function to pass the selected value to its parent component. Here are the steps to use this component:","• Use the selectedValue prop to set the initial value of the <select> element. • Use the onValueChange prop to specify the callback function that should be called when the value of the <select> element changes. • Use Array.prototype.map() on the values array to create an <option> element for each passed value. • Each item in values should be a 2-element array, where the first element is the value of the item and the second one is the displayed text for it.","Here's an example of how to use this component:"],"code":[{"lang":"jsx","text":"const Select = ({ values, onValueChange, selectedValue, ...rest }) => {\n  return (\n    <select\n      defaultValue={selectedValue}\n      onChange={({ target: { value } }) => onValueChange(value)}\n      {...rest}\n    >\n      {values.map(([value, text]) => (\n        <option key={value} value={value}>\n          {text}\n        </option>\n      ))}\n    </select>\n  );\n};"},{"lang":"jsx","text":"const choices = [\n  [\"grapefruit\", \"Grapefruit\"],\n  [\"lime\", \"Lime\"],\n  [\"coconut\", \"Coconut\"],\n  [\"mango\", \"Mango\"]\n];\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Select\n    values={choices}\n    selectedValue=\"lime\"\n    onValueChange={(val) => console.log(val)}\n  />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Uncontrolled Select Element</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-create-star-rating-component-in-react":{"intro":"In this lab, we will explore how to create a star rating component in React. The component will display a set of stars that users can interact with to set the rating value. We will use the useState() hook to manage the state of the component and handle user interactions using onMouseOver, onMouseLeave, and onClick events.","steps":[{"title":"Star Rating","body":["Create a Star component that renders each individual star with the appropriate appearance based on the parent component's state. Then, define a StarRating component that uses the useState() hook to define the rating and selection state variables with the appropriate initial values.","In StarRating, create a method named hoverOver that updates selection according to the provided event. If event is not provided or it is null, reset selection to 0. Use the .data-star-id attribute of the event's target to determine the value of selection.","Finally, render the StarRating component with an initial value of 2 by calling ReactDOM.createRoot(document.getElementById('root')).render(<StarRating value={2} />);."],"code":[{"lang":"css","text":".star {\n  color: #ff9933;\n  cursor: pointer;\n}"},{"lang":"jsx","text":"const Star = ({ marked, starId }) => {\n  return (\n    <span data-star-id={starId} className=\"star\" role=\"button\">\n      {marked ? \"\\u2605\" : \"\\u2606\"}\n    </span>\n  );\n};\n\nconst StarRating = ({ value }) => {\n  const [rating, setRating] = React.useState(parseInt(value) || 0);\n  const [selection, setSelection] = React.useState(0);\n\n  const hoverOver = (event) => {\n    let val = 0;\n    if (event && event.target && event.target.getAttribute(\"data-star-id\"))\n      val = event.target.getAttribute(\"data-star-id\");\n    setSelection(val);\n  };\n\n  return (\n    <div\n      onMouseLeave={() => hoverOver(null)}\n      onMouseOver={hoverOver}\n      onClick={(e) =>\n        setRating(e.target.getAttribute(\"data-star-id\") || rating)\n      }\n    >\n      {Array.from({ length: 5 }, (v, i) => (\n        <Star\n          starId={i + 1}\n          key={`star_${i + 1}`}\n          marked={selection ? selection >= i + 1 : rating >= i + 1}\n        />\n      ))}\n    </div>\n  );\n};"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Star Rating</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-building-reusable-react-tabs-component":{"intro":"In this lab, we will be creating a Tabs component in React that allows users to switch between different content views by clicking on a menu. We will be using the useState() hook to manage the active tab index and the map() method to render the tab menu and content view. By the end of this lab, you will have a better understanding of how to build reusable components in React using state and props.","steps":[{"title":"Tabs","body":["To render a tabbed menu and view component, follow these steps:","Here is the CSS code to style the tabbed menu and view:","Here is the JavaScript code to implement the Tabs component:","Finally, here is an example of how to use the Tabs component:"],"code":[{"lang":"css","text":".tab-menu > button {\n  cursor: pointer;\n  padding: 8px 16px;\n  border: 0;\n  border-bottom: 2px solid transparent;\n  background: none;\n}\n\n.tab-menu > button.focus {\n  border-bottom: 2px solid #007bef;\n}\n\n.tab-menu > button:hover {\n  border-bottom: 2px solid #007bef;\n}\n\n.tab-content {\n  display: none;\n}\n\n.tab-content.selected {\n  display: block;\n}"},{"lang":"jsx","text":"const TabItem = (props) => <div {...props} />;\n\nconst Tabs = ({ defaultIndex = 0, onTabClick, children }) => {\n  const [bindIndex, setBindIndex] = React.useState(defaultIndex);\n\n  const changeTab = (newIndex) => {\n    if (typeof onTabClick === \"function\") onTabClick(newIndex);\n    setBindIndex(newIndex);\n  };\n\n  const items = children.filter((item) => item.type.name === \"TabItem\");\n\n  return (\n    <div className=\"wrapper\">\n      <div className=\"tab-menu\">\n        {items.map(({ props: { index, label } }) => (\n          <button\n            key={`tab-btn-${index}`}\n            onClick={() => changeTab(index)}\n            className={bindIndex === index ? \"focus\" : \"\"}\n          >\n            {label}\n          </button>\n        ))}\n      </div>\n      <div className=\"tab-view\">\n        {items.map(({ props }) => (\n          <div\n            {...props}\n            className={`tab-content ${\n              bindIndex === props.index ? \"selected\" : \"\"\n            }`}\n            key={`tab-content-${props.index}`}\n          />\n        ))}\n      </div>\n    </div>\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Tabs defaultIndex={1} onTabClick={console.log}>\n    <TabItem label=\"A\" index={1}>\n      Lorem ipsum\n    </TabItem>\n    <TabItem label=\"B\" index={2}>\n      Dolor sit amet\n    </TabItem>\n  </Tabs>\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Tabs</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-reusable-react-toggle-component":{"intro":"In this lab, we will explore how to implement a toggle component using React. The toggle component is a common UI element used to switch between two states. We will use the useState() hook to manage the component's state and apply different CSS classes based on its state. By the end of this lab, you will have a better understanding of how to create reusable UI components in React.","steps":[{"title":"Toggle","body":["To render a toggle component, follow these steps:"],"code":[{"lang":"css","text":".toggle input[type=\"checkbox\"] {\n  display: none;\n}\n\n.toggle.on {\n  background-color: green;\n}\n\n.toggle.off {\n  background-color: red;\n}"},{"lang":"jsx","text":"const Toggle = ({ defaultToggled = false }) => {\n  const [isToggleOn, setIsToggleOn] = React.useState(defaultToggled);\n\n  return (\n    <label className={isToggleOn ? \"toggle on\" : \"toggle off\"}>\n      <input\n        type=\"checkbox\"\n        checked={isToggleOn}\n        onChange={() => setIsToggleOn(!isToggleOn)}\n      />\n      {isToggleOn ? \"ON\" : \"OFF\"}\n    </label>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<Toggle />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Toggle</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-creating-customizable-react-tooltips":{"intro":"In this lab, we will learn how to create a tooltip component in React using state and event handlers. Tooltips are small pop-up boxes that appear when the user hovers over an element, providing additional information. By the end of the lab, you will be able to create customizable tooltips that can be easily integrated into your React applications.","steps":[{"title":"Tooltip","body":["Here's a clearer, more concise, and more coherent version of the content:","This code creates a tooltip component. To use it, do the following:","• Use the useState() hook to create the show variable and set it to false. • Render a container element that contains the tooltip element and the children passed to the component. • Handle the onMouseEnter and onMouseLeave events by toggling the className of the tooltip, which is controlled by the show variable.","Here's the code for the tooltip component:"],"code":[{"lang":"css","text":".tooltip-container {\n  position: relative;\n}\n\n.tooltip-box {\n  position: absolute;\n  top: calc(100% + 5px);\n  display: none;\n  padding: 5px;\n  border-radius: 5px;\n  background: rgba(0, 0, 0, 0.7);\n  color: #fff;\n}\n\n.tooltip-box.visible {\n  display: block;\n}\n\n.tooltip-arrow {\n  position: absolute;\n  top: -10px;\n  left: 50%;\n  border-width: 5px;\n  border-style: solid;\n  border-color: transparent transparent rgba(0, 0, 0, 0.7) transparent;\n}"},{"lang":"jsx","text":"const Tooltip = ({ children, text, ...rest }) => {\n  const [show, setShow] = React.useState(false);\n\n  return (\n    <div className=\"tooltip-container\">\n      <div className={show ? \"tooltip-box visible\" : \"tooltip-box\"}>\n        {text}\n        <span className=\"tooltip-arrow\" />\n      </div>\n      <div\n        onMouseEnter={() => setShow(true)}\n        onMouseLeave={() => setShow(false)}\n        {...rest}\n      >\n        {children}\n      </div>\n    </div>\n  );\n};"},{"lang":"jsx","text":"ReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <Tooltip text=\"Simple tooltip\">\n    <button>Hover me!</button>\n  </Tooltip>\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Tooltip</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-expandable-object-tree-view":{"intro":"In this lab, we will learn how to create an expandable object tree view in React. This component is useful for displaying complex data structures in a structured and collapsible format. We will use the useState hook and recursion to render a tree view of a JSON object or array with collapsible content. By the end of this lab, you will be able to create and customize a tree view component to display your data in a clear and organized way.","steps":[{"title":"Expandable Object Tree View","body":["The following code renders a collapsible tree view of a JSON object or array. By using the useState() hook to create the isToggled state variable, you can determine the initial state of the content (collapsed/expanded) by passing the toggled prop. The appearance of the component is determined based on isParentToggled, isToggled, name, and checking for Array.isArray() on data.","The CSS styles are defined for the component's appearance, including margin, position, border, and display properties."],"code":[{"lang":"jsx","text":"const TreeView = ({\n  data,\n  toggled = true,\n  name = null,\n  isLast = true,\n  isChildElement = false,\n  isParentToggled = true\n}) => {\n  const [isToggled, setIsToggled] = React.useState(toggled);\n  const isDataArray = Array.isArray(data);\n\n  return (\n    <div\n      className={`tree-element ${isParentToggled && \"collapsed\"} ${\n        isChildElement && \"is-child\"\n      }`}\n    >\n      <span\n        className={isToggled ? \"toggler\" : \"toggler closed\"}\n        onClick={() => setIsToggled(!isToggled)}\n      />\n      {name ? <strong>&nbsp;&nbsp;{name}: </strong> : <span>&nbsp;&nbsp;</span>}\n      {isDataArray ? \"[\" : \"{\"}\n      {!isToggled && \"...\"}\n      {Object.keys(data).map((v, i, a) =>\n        typeof data[v] === \"object\" ? (\n          <TreeView\n            key={`${name}-${v}-${i}`}\n            data={data[v]}\n            isLast={i === a.length - 1}\n            name={isDataArray ? null : v}\n            isChildElement\n            isParentToggled={isParentToggled && isToggled}\n          />\n        ) : (\n          <p\n            key={`${name}-${v}-${i}`}\n            className={isToggled ? \"tree-element\" : \"tree-element collapsed\"}\n          >\n            {isDataArray ? \"\" : <strong>{v}: </strong>}\n            {data[v]}\n            {i === a.length - 1 ? \"\" : \",\"}\n          </p>\n        )\n      )}\n      {isDataArray ? \"]\" : \"}\"}\n      {!isLast ? \",\" : \"\"}\n    </div>"},{"lang":"css","text":".tree-element {\n  margin: 0 0 0 4px;\n  position: relative;\n}\n\n.tree-element.is-child {\n  margin-left: 16px;\n}\n\ndiv.tree-element::before {\n  content: \"\";\n  position: absolute;\n  top: 24px;\n  left: 1px;\n  height: calc(100% - 48px);\n  border-left: 1px solid gray;\n}\n\np.tree-element {\n  margin-left: 16px;\n}\n\n.toggler {\n  position: absolute;\n  top: 10px;\n  left: 0px;\n  width: 0;\n  height: 0;\n  border-top: 4px solid transparent;\n  border-bottom: 4px solid transparent;\n  border-left: 5px solid gray;\n  cursor: pointer;\n}\n\n.toggler.closed {\n  transform: rotate(90deg);\n}\n\n.collapsed {\n  display: none;\n}"},{"lang":"jsx","text":"const data = {\n  lorem: {\n    ipsum: \"dolor sit\",\n    amet: {\n      consectetur: \"adipiscing\",\n      elit: [\n        \"duis\",\n        \"vitae\",\n        {\n          semper: \"orci\"\n        },\n        {\n          est: \"sed ornare\"\n        },\n        \"etiam\",\n        [\"laoreet\", \"tincidunt\"],\n        [\"vestibulum\", \"ante\"]\n      ]\n    },\n    ipsum: \"primis\"\n  }\n};\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <TreeView data={data} name=\"data\" />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Expandable Object Tree View</title>\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-uncontrolled-input-field":{"intro":"In this lab, we will explore how to create an uncontrolled input field using React. An uncontrolled input field is a simple and flexible way to capture user input without managing the value state in the parent component. We will use a callback function to inform the parent about value updates, making it easy to integrate with other components and APIs.","steps":[{"title":"Uncontrolled Input Field","body":["This code renders an uncontrolled <input> element that uses a callback function to inform its parent about value updates. To use it:","• Pass the initial value down from the parent using the defaultValue prop. • Pass a callback function called onValueChange to handle value updates. • Use the onChange event to fire the callback and send the new value to the parent."],"code":[{"lang":"jsx","text":"const UncontrolledInput = ({ defaultValue, onValueChange, ...rest }) => {\n  return (\n    <input\n      defaultValue={defaultValue}\n      onChange={({ target: { value } }) => onValueChange(value)}\n      {...rest}\n    />\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(\n  <UncontrolledInput\n    type=\"text\"\n    placeholder=\"Insert some text here...\"\n    onValueChange={console.log}\n  />\n);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>Uncontrolled Input Field</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usecomponentdidupdate-hook":{"intro":"In this lab, we will learn about the useComponentDidUpdate hook in React. This hook allows us to execute a callback immediately after a component is updated, similar to the componentDidUpdate() lifecycle method of class components. We will explore how to use this hook to track changes to specific state variables and run custom logic accordingly.","steps":[{"title":"React useComponentDidUpdate Hook","body":["React useComponentDidUpdate Hook","This code provides a custom hook called useComponentDidUpdate that executes a provided callback function whenever a component is updated. Here are the steps that the hook follows:","• Create a mounted variable using the useRef() hook. This variable tracks whether the component has been mounted or not. • Use the useEffect() hook to set the value of mounted to true the first time the hook is executed. • On subsequent hook executions, run the provided callback function only if the component has already been mounted. • If a second argument condition is provided, the hook will only execute if any of its dependencies change. • This hook behaves like the componentDidUpdate() lifecycle method of class components."],"code":[{"lang":"jsx","text":"const useComponentDidUpdate = (callback, condition) => {\n  const isMounted = React.useRef(false);\n  React.useEffect(() => {\n    if (isMounted.current) {\n      callback();\n    } else {\n      isMounted.current = true;\n    }\n  }, condition);\n};\n\nconst App = () => {\n  const [value, setValue] = React.useState(0);\n  const [otherValue, setOtherValue] = React.useState(1);\n\n  useComponentDidUpdate(() => {\n    console.log(`Current value is ${value}.`);\n  }, [value]);\n\n  return (\n    <>\n      <p>\n        Value: {value}, other value: {otherValue}\n      </p>\n      <button onClick={() => setValue(value + 1)}>Increment value</button>\n      <button onClick={() => setOtherValue(otherValue + 1)}>\n        Increment other value\n      </button>\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useComponentDidUpdate Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usedelayedstate-hook":{"intro":"In this lab, we will learn how to use the useDelayedState hook in React to delay the creation of a stateful value until a certain condition is met. This hook is useful when we need to wait for data or props to load before creating a stateful value, and can help improve the performance of our application. Through practical examples, we will see how this hook can be implemented and how it can be used to update stateful values in our React components.","steps":[{"title":"React useDelayedState Hook","body":["To delay the creation of a stateful value until a condition is met, follow these steps:","• Use the useState() hook to create a stateful value containing the actual state and a boolean, loaded. • Use the useEffect() hook to update the stateful value if the condition or loaded changes. • Create a function, updateState, that only updates the state value if loaded is truthy.","Here's an example of how to use the useDelayedState hook:"],"code":[{"lang":"jsx","text":"const useDelayedState = (initialState, condition) => {\n  const [{ state, loaded }, setState] = React.useState({\n    state: null,\n    loaded: false\n  });\n\n  React.useEffect(() => {\n    if (!loaded && condition) setState({ state: initialState, loaded: true });\n  }, [condition, loaded]);\n\n  const updateState = (newState) => {\n    if (!loaded) return;\n    setState({ state: newState, loaded });\n  };\n\n  return [state, updateState];\n};"},{"lang":"jsx","text":"const App = () => {\n  const [branches, setBranches] = React.useState([]);\n  const [selectedBranch, setSelectedBranch] = useDelayedState(\n    branches[0],\n    branches.length\n  );\n\n  React.useEffect(() => {\n    const handle = setTimeout(() => {\n      setBranches([\"master\", \"staging\", \"test\", \"dev\"]);\n    }, 2000);\n    return () => {\n      handle && clearTimeout(handle);\n    };\n  }, []);\n\n  return (\n    <div>\n      <p>Selected branch: {selectedBranch}</p>\n      <select onChange={(e) => setSelectedBranch(e.target.value)}>\n        {branches.map((branch) => (\n          <option key={branch} value={branch}>\n            {branch}\n          </option>\n        ))}\n      </select>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useDelayedState Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useeffectonce-hook":{"intro":"In this lab, we will learn how to use the useEffectOnce hook in React to run a callback function at most once when a certain condition becomes true. This can be useful for situations where we want to execute a specific action only once, such as when a component mounts or when a button is clicked. By the end of this lab, you will have a better understanding of how to implement this hook in your React applications.","steps":[{"title":"React useEffectOnce Hook","body":["The code below implements a function useEffectOnce(callback, when) that runs a callback only once when a when condition becomes true.","• Create a variable hasRunOnce using the useRef() hook to keep track of the execution status of the effect. • Use the useEffect() hook that runs only when the when condition changes. • Inside the useEffect() hook, check if when is true and the effect has not executed before. If both are true, run callback and set hasRunOnce to true.","Here's an example usage of useEffectOnce():"],"code":[{"lang":"jsx","text":"const useEffectOnce = (callback, when) => {\n  const hasRunOnce = React.useRef(false);\n  React.useEffect(() => {\n    if (when && !hasRunOnce.current) {\n      callback();\n      hasRunOnce.current = true;\n    }\n  }, [when]);\n};"},{"lang":"jsx","text":"const App = () => {\n  const [clicked, setClicked] = React.useState(false);\n  useEffectOnce(() => {\n    console.log(\"mounted\");\n  }, clicked);\n  return <button onClick={() => setClicked(true)}>Click me</button>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useEffectOnce Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useerror-hook":{"intro":"In this lab, we will learn how to create an error dispatcher using the useError hook in React. The hook allows us to create a state variable that holds an error and throw it whenever it's truthy. We will also use the useCallback hook to update the state and return the cached function. By the end of this lab, you will be able to effectively handle errors in your React applications.","steps":[{"title":"React useError Hook","body":["This code creates an error dispatcher. It uses three React hooks to manage the error state and dispatch it to the user interface.","• The useState() hook creates a state variable called error that holds the error object. It takes an initial value of err, which is passed in as an argument to the hook.","• The useEffect() hook is used to \"throw\" the error whenever it's truthy. This hook takes a function and an array of dependencies as arguments. In this case, the function checks if the error state variable is truthy (i.e. not null, undefined, 0, false, or an empty string), and throws it if it is. The array of dependencies is [error], which means the effect will be re-run whenever the error variable changes.","• The useCallback() hook is used to create a cached function called dispatchError, which updates the error state variable and returns the new function. This hook takes a function and an array of dependencies as arguments. In this case, the function takes an argument err, which is the new error object to be dispatched. The array of dependencies is [], which means the cached function will only be re-created if the component is re-rendered."],"code":[{"lang":"jsx","text":"const useError = (err = null) => {\n  const [error, setError] = React.useState(err);\n\n  React.useEffect(() => {\n    if (error) {\n      throw error;\n    }\n  }, [error]);\n\n  const dispatchError = React.useCallback((err) => {\n    setError(err);\n  }, []);\n\n  return dispatchError;\n};\n\nconst ErrorButton = () => {\n  const dispatchError = useError();\n\n  const clickHandler = () => {\n    dispatchError(new Error(\"Error!\"));\n  };\n\n  return <button onClick={clickHandler}>Throw error</button>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<ErrorButton />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useError Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useeventlistener-hook":{"intro":"In this lab, we will be exploring the use of the useEventListener hook in React. The purpose of this lab is to help you understand how to add event listeners to elements in a React application, and how to clean them up properly to avoid memory leaks. Through practical examples, you will learn how to use this hook to create more interactive and responsive user interfaces.","steps":[{"title":"React useEventListener Hook","body":["This function adds an event listener for the specified event type on the given element. To use this function, follow these steps:","• Use the useRef() hook to create a ref that will hold the handler. • Use the useEffect() hook to update the value of the savedHandler ref any time the handler changes. • Use the useEffect() hook to add an event listener to the given element and clean up when unmounting. • Omit the last argument, el, to use the Window by default.","And here's an example usage of the useEventListener() function:"],"code":[{"lang":"jsx","text":"const useEventListener = (type, handler, el = window) => {\n  const savedHandler = React.useRef(handler);\n\n  React.useEffect(() => {\n    savedHandler.current = handler;\n  }, [handler]);\n\n  React.useEffect(() => {\n    const listener = (e) => savedHandler.current(e);\n\n    el.addEventListener(type, listener);\n\n    return () => {\n      el.removeEventListener(type, listener);\n    };\n  }, [type, el]);\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const [coords, setCoords] = React.useState({ x: 0, y: 0 });\n\n  const updateCoords = React.useCallback(\n    ({ clientX, clientY }) => {\n      setCoords({ x: clientX, y: clientY });\n    },\n    [setCoords]\n  );\n\n  useEventListener(\"mousemove\", updateCoords);\n\n  return (\n    <p>\n      Mouse coordinates: {coords.x}, {coords.y}\n    </p>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useEventListener Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usefetch-hook":{"intro":"In this lab, we will learn about the useFetch hook in React. This hook allows us to implement the fetch() method in a declarative manner, making it easier to fetch data from APIs and update the component state. We will create a custom hook that takes a URL and options, and asynchronously calls fetch() to update the response, error, and abort state variables.","steps":[{"title":"React useFetch Hook","body":["• The purpose of the code is to implement a fetch() call in a declarative manner using React hooks. • The useFetch hook takes two parameters: a url and options object. • The hook initializes three state variables using the useState() hook: response, error, and abort. • The useEffect() hook is used to asynchronously call fetch() and update the state variables accordingly. • An AbortController is used to allow aborting the request, and it's used to cancel the request when the component unmounts. • The hook returns an object containing the response, error, and abort state variables. • The ImageFetch component uses the useFetch hook…"],"code":[{"lang":"jsx","text":"const useFetch = (url, options) => {\n  const [response, setResponse] = React.useState(null);\n  const [error, setError] = React.useState(null);\n  const [abort, setAbort] = React.useState(() => {});\n\n  React.useEffect(() => {\n    const abortController = new AbortController();\n    const signal = abortController.signal;\n\n    const fetchData = async () => {\n      try {\n        const res = await fetch(url, { ...options, signal });\n        const json = await res.json();\n        setResponse(json);\n      } catch (error) {\n        setError(error);\n      }\n    };\n    fetchData();\n\n    return () => {\n      abort();\n    };\n  }, []);\n\n  return { response, error, abort };\n};\n\nconst ImageFetch = (props) => {\n  const res = useFetch(\"https://dog.ceo/api/breeds/image/random\", {});\n\n  if (!res.response) {\n    return <div>Loading...</div>;\n  }\n\n  const imageUrl = res.response.message;\n\n  return (\n    <div>\n      <img src={imageUrl} alt=\"avatar\" width={400} height=\"auto\" />\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<ImageFetch />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useFetch Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usehash-hook":{"intro":"In this lab, we will learn how to use the useHash hook in React to track and update the browser's location hash value. This hook is useful for creating single-page applications where different components or sections of the page are displayed based on the hash value. By the end of this lab, you will be able to implement the useHash hook in your React projects and enhance the user experience of your web applications.","steps":[{"title":"React useHash Hook","body":["This code tracks and updates the browser's location hash value. To use it, follow these steps:","• Use the useState() hook to lazily get the hash property of the Location object. • Use the useCallback() hook to create a handler that updates the hash state when the 'hashchange' event is fired. • Use the useEffect() hook to add a listener for the 'hashchange' event when mounting and clean it up when unmounting. • Use the useCallback() hook to create a function that updates the hash property of the Location object with the given value. • In your component, call useHash() to get the current hash value and an updateHash() function to change it. • Use the updateHash() function to change the hash value. • Render the current hash…"],"code":[{"lang":"jsx","text":"const useHash = () => {\n  const [hash, setHash] = React.useState(() => window.location.hash);\n\n  const hashChangeHandler = React.useCallback(() => {\n    setHash(window.location.hash);\n  }, []);\n\n  React.useEffect(() => {\n    window.addEventListener(\"hashchange\", hashChangeHandler);\n    return () => {\n      window.removeEventListener(\"hashchange\", hashChangeHandler);\n    };\n  }, []);\n\n  const updateHash = React.useCallback(\n    (newHash) => {\n      if (newHash !== hash) window.location.hash = newHash;\n    },\n    [hash]\n  );\n\n  return [hash, updateHash];\n};\n\nconst MyApp = () => {\n  const [hash, setHash] = useHash();\n\n  React.useEffect(() => {\n    setHash(\"#list\");\n  }, []);\n\n  return (\n    <>\n      <p>Current hash value: {hash}</p>\n      <p>Edit hash: </p>\n      <input value={hash} onChange={(e) => setHash(e.target.value)} />\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useHash Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usehover-hook":{"intro":"In this lab, we will explore the implementation of a custom hook called useHover in React. This hook will handle the event of hovering over a wrapped component and update the state accordingly. By the end of this lab, you will have a better understanding of how to create and use custom hooks in React to enhance the functionality of your components.","steps":[{"title":"React useHover Hook","body":["This code creates a custom hook that handles hovering over a wrapped component.","• Use useState() to create a variable that holds the hovering state. • Use useCallback() to memoize two handler functions that update the state. • Use useCallback() to create a callback ref and create or update the listeners for the 'mouseover' and 'mouseout' events. • Use useRef() to keep track of the last node passed to callbackRef to be able to remove its listeners.","This is an example usage of the hook:"],"code":[{"lang":"jsx","text":"const useHover = () => {\n  const [isHovering, setIsHovering] = React.useState(false);\n  const handleMouseOver = React.useCallback(() => setIsHovering(true), []);\n  const handleMouseOut = React.useCallback(() => setIsHovering(false), []);\n  const nodeRef = React.useRef();\n  const callbackRef = React.useCallback(\n    (node) => {\n      if (nodeRef.current) {\n        nodeRef.current.removeEventListener(\"mouseover\", handleMouseOver);\n        nodeRef.current.removeEventListener(\"mouseout\", handleMouseOut);\n      }\n      nodeRef.current = node;\n      if (nodeRef.current) {\n        nodeRef.current.addEventListener(\"mouseover\", handleMouseOver);\n        nodeRef.current.addEventListener(\"mouseout\", handleMouseOut);\n      }\n    },\n    [handleMouseOver, handleMouseOut]\n  );\n\n  return [callbackRef, isHovering];\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const [hoverRef, isHovering] = useHover();\n  return <div ref={hoverRef}>{isHovering ? \"Hovering\" : \"Not hovering\"}</div>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useHover Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useintersectionobserver-hook":{"intro":"In this lab, we will learn how to use the useIntersectionObserver hook in React to observe the visibility changes of a given element. This hook can be used to track when an element becomes visible on the screen and trigger certain actions accordingly. By the end of this lab, you will be able to implement this hook in your React projects to create more interactive and dynamic user interfaces.","steps":[{"title":"React useIntersectionObserver Hook","body":["React useIntersectionObserver Hook","To observe visibility changes for a given element, follow these steps:","• Use the useState() hook to store the intersection value of the given element. • Create an IntersectionObserver with the given options and an appropriate callback to update the isIntersecting state variable. • Use the useEffect() hook to call IntersectionObserver.observe() when mounting the component and clean up using IntersectionObserver.unobserve() when unmounting.","Here's an example implementation:"],"code":[{"lang":"jsx","text":"const useIntersectionObserver = (ref, options) => {\n  const [isIntersecting, setIsIntersecting] = React.useState(false);\n\n  React.useEffect(() => {\n    const observer = new IntersectionObserver(([entry]) => {\n      setIsIntersecting(entry.isIntersecting);\n    }, options);\n\n    if (ref.current) {\n      observer.observe(ref.current);\n    }\n\n    return () => {\n      observer.unobserve(ref.current);\n    };\n  }, [ref, options]);\n\n  return isIntersecting;\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const ref = React.useRef();\n  const onScreen = useIntersectionObserver(ref, { threshold: 0.5 });\n\n  return (\n    <div>\n      <div style={{ height: \"100vh\" }}>Scroll down</div>\n      <div style={{ height: \"100vh\" }} ref={ref}>\n        <p>{onScreen ? \"Element is on screen.\" : \"Scroll more!\"}</p>\n      </div>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useIntersectionObserver Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usekeypress-hook":{"intro":"In this lab, we will learn how to create a custom React hook called useKeyPress that listens for changes in the pressed state of a given key. This hook will be useful in scenarios where we need to detect whether a specific key is being pressed by the user. We will use the useState and useEffect hooks to handle state and event listeners, respectively.","steps":[{"title":"React useKeyPress Hook","body":["This function listens for changes in the pressed state of a given key. To use it:","• Call useKeyPress() with the target key as an argument. • useKeyPress() returns a boolean value that indicates whether the key is currently pressed. • The function uses the useState() hook to create a state variable that holds the pressed state of the given key. • It defines two handler functions that update the state variable on key down or key up accordingly. • The useEffect() hook and EventTarget.addEventListener() are used to handle the 'keydown' and 'keyup' events. • Finally, EventTarget.removeEventListener() is used to perform cleanup after the component is unmounted.","Here's an example usage of useKeyPress() in a React component:"],"code":[{"lang":"jsx","text":"const useKeyPress = (targetKey) => {\n  const [isKeyPressed, setKeyPressed] = React.useState(false);\n\n  const handleKeyDown = ({ key }) => {\n    if (key === targetKey) setKeyPressed(true);\n  };\n\n  const handleKeyUp = ({ key }) => {\n    if (key === targetKey) setKeyPressed(false);\n  };\n\n  React.useEffect(() => {\n    window.addEventListener(\"keydown\", handleKeyDown);\n    window.addEventListener(\"keyup\", handleKeyUp);\n\n    return () => {\n      window.removeEventListener(\"keydown\", handleKeyDown);\n      window.removeEventListener(\"keyup\", handleKeyUp);\n    };\n  }, [targetKey]);\n\n  return isKeyPressed;\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const isWKeyPressed = useKeyPress(\"w\");\n\n  return <p>The \"w\" key is {!isWKeyPressed ? \"not \" : \"\"}pressed!</p>;\n};\n\nReactDOM.render(<MyApp />, document.getElementById(\"root\"));"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useKeyPress Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-uselocalstorage-hook":{"intro":"In this lab, we will be exploring the useLocalStorage hook in React. The purpose of this lab is to help you understand how to create a stateful value that is persisted to localStorage and a function to update it. You will learn how to use the useState hook, try-catch block, and Storage.getItem() and Storage.setItem() methods to store and retrieve data from localStorage. By the end of this lab, you will have gained a better understanding of how to build React applications that utilize localStorage to store and persist data.","steps":[{"title":"React useLocalStorage Hook","body":["This function creates a value that is saved to localStorage and a function to modify it. Here's how it works:","• To create the value, use the useState() hook with a function to initialize it lazily. • To retrieve the saved value from localStorage, use a try...catch block and Storage.getItem(). If there's no saved value, use Storage.setItem() to store the defaultValue and use it as the initial state. If there's an error, use defaultValue. • Define a function that updates the state variable with the passed value and uses Storage.setItem() to save it.","You can use this function in your app like this:"],"code":[{"lang":"jsx","text":"const useLocalStorage = (keyName, defaultValue) => {\n  const [storedValue, setStoredValue] = React.useState(() => {\n    try {\n      const value = window.localStorage.getItem(keyName);\n\n      if (value) {\n        return JSON.parse(value);\n      } else {\n        window.localStorage.setItem(keyName, JSON.stringify(defaultValue));\n        return defaultValue;\n      }\n    } catch (err) {\n      return defaultValue;\n    }\n  });\n\n  const setValue = (newValue) => {\n    try {\n      window.localStorage.setItem(keyName, JSON.stringify(newValue));\n    } catch (err) {}\n    setStoredValue(newValue);\n  };\n\n  return [storedValue, setValue];\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const [name, setName] = useLocalStorage(\"name\", \"John\");\n\n  return <input value={name} onChange={(e) => setName(e.target.value)} />;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useLocalStorage Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usemap-hook":{"intro":"In this lab, we will explore the useMap hook in React, which creates a stateful Map object and a set of functions to manipulate it. By using this hook, we can easily manage and update key-value pairs in our React components without having to write complex and error-prone logic. This lab will guide you through the implementation of the useMap hook and demonstrate its usage in a sample application.","steps":[{"title":"React useMap Hook","body":["• The useMap() hook creates a stateful Map object and a set of functions to manipulate it using React hooks. • The useState() hook initializes the Map state with the initialValue. • The useMemo() hook creates a set of non-mutating actions that manipulate the map state variable using the state setter to create a new Map every time. • The useMap() hook returns an array containing the map state variable and the created actions. • The MyApp component uses the useMap() hook to initialize the stateful Map object and provides buttons to add, reset, and remove items from the Map. • The JSON.stringify() function formats the Map object…"],"code":[{"lang":"jsx","text":"const useMap = (initialValue) => {\n  const [map, setMap] = React.useState(new Map(initialValue));\n\n  const actions = React.useMemo(\n    () => ({\n      set: (key, value) =>\n        setMap((prevMap) => {\n          const nextMap = new Map(prevMap);\n          nextMap.set(key, value);\n          return nextMap;\n        }),\n      remove: (key) =>\n        setMap((prevMap) => {\n          const nextMap = new Map(prevMap);\n          nextMap.delete(key);\n          return nextMap;\n        }),\n      clear: () => setMap(new Map())\n    }),\n    [setMap]\n  );\n\n  return [map, actions];\n};\n\nconst MyApp = () => {\n  const [map, { set, remove, clear }] = useMap([[\"apples\", 10]]);\n\n  const handleAdd = () => set(Date.now(), new Date().toJSON());\n  const handleReset = () => clear();\n  const handleRemove = () => remove(\"apples\");\n\n  return (\n    <div>\n      <button onClick={handleAdd}>Add</button>\n      <button onClick={handleReset}>Reset</button>\n      <button onClick={handleRemove} disabled={!map.has(\"apples\")}>\n        Remove apples\n      </button>\n      <pre>{JSON.stringify(Object.fromEntries(map), null, 2)}</pre>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useMap Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usemediaquery-hook":{"intro":"In this lab, we will explore the use of the useMediaQuery hook in React. This hook allows us to check if the current environment matches a given media query and return the appropriate value. We will learn how to use this hook to create responsive components that change their behavior based on the screen size.","steps":[{"title":"React useMediaQuery Hook","body":[],"code":[{"lang":"jsx","text":"const useMediaQuery = (query, whenTrue, whenFalse) => {\n  if (\n    typeof window === \"undefined\" ||\n    typeof window.matchMedia === \"undefined\"\n  ) {\n    return whenFalse;\n  }\n\n  const mediaQuery = window.matchMedia(query);\n  const [match, setMatch] = React.useState(!!mediaQuery.matches);\n\n  React.useEffect(() => {\n    const handler = () => setMatch(!!mediaQuery.matches);\n    mediaQuery.addListener(handler);\n    return () => mediaQuery.removeListener(handler);\n  }, [mediaQuery]);\n\n  return match ? whenTrue : whenFalse;\n};"},{"lang":"jsx","text":"const ResponsiveText = () => {\n  const text = useMediaQuery(\n    \"(max-width: 400px)\",\n    \"Less than 400px wide\",\n    \"More than 400px wide\"\n  );\n\n  return <span>{text}</span>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<ResponsiveText />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useMediaQuery Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usemutationobserver-hook":{"intro":"In this lab, we will learn how to use the useMutationObserver hook in React to watch for changes made to the DOM tree using a MutationObserver. The hook allows us to specify a callback function to be executed when a change is observed, and we can also provide options to customize the observer's behavior. Through this lab, we will be able to understand how to implement the useMutationObserver hook in our React applications.","steps":[{"title":"React useMutationObserver Hook","body":["React useMutationObserver Hook","To watch changes made to the DOM tree, the useMutationObserver hook can be used. Here's how it works:","• The hook takes in three parameters: ref, callback, and options. • Inside the hook, a useEffect() hook is used that depends on the values of callback and options. • If the given ref is initialized, a new MutationObserver is created and passed the callback. • MutationObserver.observe() is called with the given options to watch the given ref for changes. • MutationObserver.disconnect() is used to remove the observer from the ref when the component unmounts.","In the App component, the useMutationObserver hook is used to watch for changes made to the mutationRef element. The incrementMutationCount function is passed as the callback."],"code":[{"lang":"jsx","text":"const useMutationObserver = (\n  ref,\n  callback,\n  options = {\n    attributes: true,\n    characterData: true,\n    childList: true,\n    subtree: true\n  }\n) => {\n  React.useEffect(() => {\n    if (!ref.current) return;\n\n    const observer = new MutationObserver(callback);\n    observer.observe(ref.current, options);\n\n    return () => observer.disconnect();\n  }, [callback, options, ref]);\n};"},{"lang":"jsx","text":"const App = () => {\n  const mutationRef = React.useRef();\n  const [mutationCount, setMutationCount] = React.useState(0);\n\n  const incrementMutationCount = React.useCallback(() => {\n    setMutationCount((count) => count + 1);\n  }, []);\n\n  useMutationObserver(mutationRef, incrementMutationCount);\n\n  const [content, setContent] = React.useState(\"Hello world\");\n\n  return (\n    <>\n      <label htmlFor=\"content-input\">Edit this to update the text:</label>\n      <textarea\n        id=\"content-input\"\n        style={{ width: \"100%\" }}\n        value={content}\n        onChange={(e) => setContent(e.target.value)}\n      />\n      <div style={{ width: \"100%\" }} ref={mutationRef}>\n        <div\n          style={{\n            resize: \"both\",\n            overflow: \"auto\",\n            maxWidth: \"100%\",\n            border: \"1px solid black\"\n          }}\n        >\n          <h2>Resize or change the content:</h2>\n          <p>{content}</p>\n        </div>\n      </div>\n      <div>\n        <h3>Mutation count {mutationCount}</h3>\n      </div>\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useMutationObserver Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useonwindowscroll-hook":{"intro":"In this lab, we will explore how to use the useOnWindowScroll hook in React to execute a callback whenever the window is scrolled. This hook allows us to add a scroll listener to the Window global object and remove it when the component unmounts. By using this hook, we can easily add custom scroll behavior to our React components.","steps":[{"title":"React useOnWindowScroll Hook","body":["This function executes a callback function every time the window is scrolled. To implement it:","• Use the useRef() hook to create a reference variable, listener. • Use the useEffect() hook and EventTarget.addEventListener() to listen to the 'scroll' event of the Window object, and assign the listener reference to listener.current. • Use EventTarget.removeEventListener() to remove any existing listeners when the component unmounts.","To test the function, you can use it in a component like this:","This will log the vertical scroll position of the window every time it's scrolled."],"code":[{"lang":"jsx","text":"const useOnWindowScroll = (callback) => {\n  const listener = React.useRef(null);\n\n  React.useEffect(() => {\n    if (listener.current) {\n      window.removeEventListener(\"scroll\", listener.current);\n    }\n    listener.current = () => {\n      callback(window.pageYOffset);\n    };\n    window.addEventListener(\"scroll\", listener.current);\n    return () => {\n      window.removeEventListener(\"scroll\", listener.current);\n    };\n  }, [callback]);\n};"},{"lang":"jsx","text":"const App = () => {\n  useOnWindowScroll((scrollY) => console.log(`scroll Y: ${scrollY}`));\n  return <p style={{ height: \"300vh\" }}>Scroll and check the console</p>;\n};\n\nReactDOM.render(<App />, document.getElementById(\"root\"));"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useOnWindowScroll Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usepersistedstate-hook":{"intro":"In this lab, we will learn about the usePersistedState hook in React, which allows us to persist a stateful value in localStorage. We will explore how to initialize and update the stored value, as well as how to handle changes to the key name. By the end of this lab, you will be able to use this hook in your React applications to ensure that certain data is stored and can be retrieved even after a page refresh.","steps":[{"title":"React usePersistedState Hook","body":["This hook returns a stateful value that is persisted in localStorage, along with a function that can be used to update it. To use it, follow these steps:","• Use the useState() hook to initialize the value to defaultValue. • Use the useRef() hook to create a ref that will hold the name of the value in Window.localStorage. • Use 3 instances of the useEffect() hook for initialization, value change, and name change respectively. • When the component is first mounted, use Storage.getItem() to update value if there's a stored value, or Storage.setItem() to persist the current value. • When value is updated, use Storage.setItem() to store the new value. • When name is updated, use Storage.setItem() to create the new key, update the nameRef, and use Storage.removeItem() to remove the…"],"code":[{"lang":"jsx","text":"const usePersistedState = (name, defaultValue) => {\n  const [value, setValue] = React.useState(defaultValue);\n  const nameRef = React.useRef(name);\n\n  React.useEffect(() => {\n    try {\n      const storedValue = localStorage.getItem(name);\n      if (storedValue !== null) {\n        setValue(storedValue);\n      } else {\n        localStorage.setItem(name, defaultValue);\n      }\n    } catch {\n      setValue(defaultValue);\n    }\n  }, []);\n\n  React.useEffect(() => {\n    try {\n      localStorage.setItem(nameRef.current, value);\n    } catch {}\n  }, [value]);\n\n  React.useEffect(() => {\n    const lastName = nameRef.current;\n    if (name !== lastName) {\n      try {\n        localStorage.setItem(name, value);\n        nameRef.current = name;\n        localStorage.removeItem(lastName);\n      } catch {}\n    }\n  }, [name]);\n\n  return [value, setValue];\n};"},{"lang":"jsx","text":"const MyComponent = ({ name }) => {\n  const [value, setValue] = usePersistedState(name, 10);\n\n  const handleInputChange = (event) => {\n    setValue(event.target.value);\n  };\n\n  return <input value={value} onChange={handleInputChange} />;\n};\n\nconst MyApp = () => {\n  const [name, setName] = React.useState(\"my-value\");\n\n  const handleInputChange = (event) => {\n    setName(event.target.value);\n  };\n\n  return (\n    <>\n      <MyComponent name={name} />\n      <input value={name} onChange={handleInputChange} />\n    </>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React usePersistedState Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useportal-hook":{"intro":"In this lab, we will be exploring the use of the usePortal hook in React. The purpose of this hook is to create a portal that allows rendering of children outside the parent component. We will learn how to use the useState(), useCallback(), and useEffect() hooks to create and manage a portal, as well as how to use ReactDOM.createPortal() and ReactDOM.unmountComponentAtNode() to render and remove the portal.","steps":[{"title":"React usePortal Hook","body":["To create a portal that renders children outside the parent component, follow these steps:","• Use the useState() hook to create a state variable that holds the render() and remove() functions for the portal. • Use ReactDOM.createPortal() and ReactDOM.unmountComponentAtNode() to create a portal and a function to remove it. Use the useCallback() hook to wrap and memoize these functions as createPortal(). • Use the useEffect() hook to call createPortal() and update the state variable any time el's value changes. • Finally, return the render() function of the state variable.","Here's an example implementation:","To use this hook, create a component that calls usePortal() with the desired DOM element as an argument. This component can then use the returned render() function to render content in the portal:"],"code":[{"lang":"jsx","text":"const usePortal = (el) => {\n  const [portal, setPortal] = React.useState({\n    render: () => null,\n    remove: () => null\n  });\n\n  const createPortal = React.useCallback((el) => {\n    const Portal = ({ children }) => ReactDOM.createPortal(children, el);\n    const remove = () => ReactDOM.unmountComponentAtNode(el);\n    return { render: Portal, remove };\n  }, []);\n\n  React.useEffect(() => {\n    if (el) portal.remove();\n    const newPortal = createPortal(el);\n    setPortal(newPortal);\n    return () => newPortal.remove(el);\n  }, [el]);\n\n  return portal.render;\n};"},{"lang":"jsx","text":"const App = () => {\n  const Portal = usePortal(document.querySelector(\"title\"));\n\n  return (\n    <p>\n      Hello world!\n      <Portal>Portalized Title</Portal>\n    </p>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<App />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React usePortal Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useprevious-hook":{"intro":"In this lab, we will explore the use of the usePrevious hook in React. This custom hook allows us to store the previous state or props of a component, which can be useful in a variety of scenarios. By creating a simple counter component and using the usePrevious hook, we will demonstrate how to implement this functionality in your React projects.","steps":[{"title":"React usePrevious Hook","body":["To store the previous state or props, you can create a custom hook. Here are the steps:","• Define a custom hook that takes a value argument. • Use the useRef() hook to create a ref for the value. • Use the useEffect() hook to remember the latest value. • Return the ref.current value.","Here's an example of using the usePrevious hook:"],"code":[{"lang":"jsx","text":"const usePrevious = (value) => {\n  const ref = React.useRef();\n  React.useEffect(() => {\n    ref.current = value;\n  });\n  return ref.current;\n};"},{"lang":"jsx","text":"const Counter = () => {\n  const [value, setValue] = React.useState(0);\n  const lastValue = usePrevious(value);\n\n  return (\n    <div>\n      <p>\n        Current: {value} - Previous: {lastValue}\n      </p>\n      <button onClick={() => setValue(value + 1)}>Increment</button>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<Counter />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React usePrevious Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usesessionstorage-hook":{"intro":"In this lab, we will be learning how to use the useSessionStorage hook in React to persist stateful values to sessionStorage. We will learn how to initialize the value lazily, retrieve and store values using Storage.getItem() and Storage.setItem(), and how to update the state variable using the defined function. By the end of this lab, you will have a better understanding of how to use sessionStorage to store and retrieve data within a React application.","steps":[{"title":"React useSessionStorage Hook","body":["To create a stateful value that is persisted to sessionStorage, and a function to update it, follow these steps:","• Use the useState() hook with a function to initialize its value lazily. • Use a try...catch block and Storage.getItem() to try and get the value from Window.sessionStorage. If no value is found, use Storage.setItem() to store the defaultValue and use it as the initial state. If an error occurs, use defaultValue as the initial state. • Define a function that will update the state variable with the passed value and use Storage.setItem() to store it.","Here is an example implementation:","You can use this hook in your app like this:"],"code":[{"lang":"jsx","text":"const useSessionStorage = (keyName, defaultValue) => {\n  const [storedValue, setStoredValue] = React.useState(() => {\n    try {\n      const value = window.sessionStorage.getItem(keyName);\n\n      if (value) {\n        return JSON.parse(value);\n      } else {\n        window.sessionStorage.setItem(keyName, JSON.stringify(defaultValue));\n        return defaultValue;\n      }\n    } catch (err) {\n      return defaultValue;\n    }\n  });\n\n  const setValue = (newValue) => {\n    try {\n      window.sessionStorage.setItem(keyName, JSON.stringify(newValue));\n    } catch (err) {}\n    setStoredValue(newValue);\n  };\n\n  return [storedValue, setValue];\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const [name, setName] = useSessionStorage(\"name\", \"John\");\n\n  return <input value={name} onChange={(e) => setName(e.target.value)} />;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useSessionStorage Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-useset-hook":{"intro":"In this lab, we will explore how to create a stateful Set object in a React component using the useSet hook. This hook provides a simple and efficient way to manipulate a set of values in a component and can be customized to fit the specific needs of the application. By the end of this lab, you will have a better understanding of how to implement and use this powerful hook in your React projects.","steps":[{"title":"React useSet Hook","body":["This function creates a Set object with state and a set of functions that can manipulate the state.","• Call useState() and the Set constructor to create a new Set from the initialValue. • Use useMemo() to create a set of non-mutating functions that can manipulate the set state variable. Use the state setter to create a new Set every time. • Return both the set state variable and the created actions.","Here's an example implementation of this function:","Here's an example usage of this function:"],"code":[{"lang":"jsx","text":"const useSet = (initialValue) => {\n  const [set, setSet] = React.useState(new Set(initialValue));\n\n  const actions = React.useMemo(\n    () => ({\n      add: (item) => setSet((prevSet) => new Set([...prevSet, item])),\n      remove: (item) =>\n        setSet((prevSet) => new Set([...prevSet].filter((i) => i !== item))),\n      clear: () => setSet(new Set())\n    }),\n    [setSet]\n  );\n\n  return [set, actions];\n};"},{"lang":"jsx","text":"const MyApp = () => {\n  const [set, { add, remove, clear }] = useSet(new Set([\"apples\"]));\n\n  return (\n    <div>\n      <button onClick={() => add(String(Date.now()))}>Add</button>\n      <button onClick={() => clear()}>Reset</button>\n      <button onClick={() => remove(\"apples\")} disabled={!set.has(\"apples\")}>\n        Remove apples\n      </button>\n      <pre>{JSON.stringify([...set], null, 2)}</pre>\n    </div>\n  );\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<MyApp />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useSet Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"},"labex-react-react-usetoggler-hook":{"intro":"In this lab, we will explore the useToggler hook in React. This hook provides a simple and efficient way to create a boolean state variable that can be toggled between its two states. By the end of this lab, you will have a better understanding of how to use this hook in your React applications to create toggle functionality for your components.","steps":[{"title":"React useToggler Hook","body":["To create a boolean state variable that can be toggled between its two states, follow these steps:","• Use the useState() hook to create the value state variable and its setter. • Create a function that toggles the value of the value state variable and memoize it, using the useCallback() hook. • Return the value state variable and the memoized toggler function.","Here is an example implementation:","You can then use this hook in your components, like this:"],"code":[{"lang":"jsx","text":"const useToggler = (initialState) => {\n  const [value, setValue] = React.useState(initialState);\n\n  const toggleValue = React.useCallback(() => setValue((prev) => !prev), []);\n\n  return [value, toggleValue];\n};"},{"lang":"jsx","text":"const Switch = () => {\n  const [val, toggleVal] = useToggler(false);\n  return <button onClick={toggleVal}>{val ? \"ON\" : \"OFF\"}</button>;\n};\n\nReactDOM.createRoot(document.getElementById(\"root\")).render(<Switch />);"}]}],"commands":[],"reference":[{"path":"index.html","text":"<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <title>React useToggler Hook</title>\n  </head>\n\n  <body>\n    <!-- partial:index.partial.html -->\n    <div id=\"root\"></div>\n    <!-- partial -->\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.2.0/umd/react.development.js\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.2.0/umd/react-dom.development.js\"></script>\n    <script src=\"https://unpkg.com/@babel/standalone/babel.min.js\"></script>\n    <script src=\"./script.js\" type=\"text/babel\"></script>\n  </body>\n</html>"}],"source":"30-seconds/30-seconds-of-code · by Lotus-7 · CC-BY-4.0"}};
